#include <stdio.h>
#include <stdlib.h>

#define MAX_N 100

long memo[MAX_N][MAX_N];
int computed[MAX_N][MAX_N];

long binom(int n, int k) {
    if (computed[n][k]) {
        return memo[n][k];
    }
    if (k == 0 || k == n) {
        memo[n][k] = 1;
    } else {
        memo[n][k] = binom(n-1, k-1) + binom(n-1, k);
    }
    computed[n][k] = 1;
    return memo[n][k];
}

int main(int argc, char *argv[]) {
    if (argc < 3) {
        printf("NO_INPUT\n");
        return 0;
    }
    int n = atoi(argv[1]);
    int k = atoi(argv[2]);
    if (n < 0 || k < 0 || k > n) {
        printf("OUT_OF_RANGE\n");
        return 0;
    }
    long result = binom(n, k);
    printf("%ld\n", result);
    return 0;
}
